WITH diario AS (
  SELECT date_trunc('day', creado_en) AS dia, count(*) AS n FROM usuarios GROUP BY 1
)
SELECT dia, n, sum(n) OVER (ORDER BY dia) AS acumulado FROM diario ORDER BY dia DESC LIMIT 14;

